examples.code:
age = 20
if age >= 18:
    print("Adult")
else:
    print("Minor")

temp = 15
if temp > 30:
    print("Hot")
elif temp > 15:
    print("Warm")
elif temp > 0:
    print("Cool")
else:
    print("Freezing")

